<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue';
import {onBeforeRouteLeave,onBeforeRouteUpdate,useRoute,useRouter} from 'vue-router';
import {ArrowLeft,ArrowUpRight,CheckCircle2,Copy,Download,FileArchive,History,LoaderCircle,Package,Plus,RefreshCw,Save,Search,Share2,ShieldCheck,Trash2,X} from 'lucide-vue-next';
import type {DatasetRelease,DatasetReleasePreview,ReleaseAsset,ReleaseList,ReleaseShare} from '../../../../packages/shared/src/releases';
import {ApiError,isUnknownOperationError,patch,post,removeAndVerify,request,verifyDeletion} from '../api';
import {credentialContext} from '../access-context';
import {releaseFormSuggestions,acceptReleaseHint,canAcceptReleaseHint} from '../release-form-hints';
import {refreshedReleaseNotes,releaseCleanupWarning,shareableReleaseAssets} from '../release-ui';
import {createReleaseCandidateSaver,createReleaseReader,createReleaseRequestScope,releaseListEmptyState,retainReleaseResult} from '../release-requests';
import {releaseDialogKey} from '../release-dialog';
import {useAppStore} from '../stores/app';
import ReleaseMarkdown from './SafeMarkdown.vue';
import WorkflowSteps from './WorkflowSteps.vue';
const props=defineProps<{base:string;branch:string}>(),emit=defineEmits<{'open-version':[commitId:string]}>(),app=useAppStore(),route=useRoute(),router=useRouter();
const items=ref<DatasetRelease[]>([]),capabilities=ref<ReleaseList['capabilities']>({manage:false,share:false,export:false,hidden:false});
const busy=ref(false),error=ref(''),actionNotice=ref(''),readbackNotice=ref(''),search=ref(''),filter=ref('all');
const kind=ref<'releases'|'snapshots'>(route.query.releaseKind==='snapshots'?'snapshots':'releases');
const selectedId=ref(typeof route.query.release==='string'?route.query.release:''),selected=computed(()=>items.value.find(item=>item.id===selectedId.value));
const visible=computed(()=>items.value.filter(item=>(filter.value==='all'||filter.value==='published'&&item.status==='published'||filter.value==='ready'&&item.status==='ready'||filter.value==='drafts'&&['draft','queued','building','ready','failed'].includes(item.status)||filter.value==='processing'&&['draft','queued','building','failed'].includes(item.status))&&(item.version+' '+item.title).toLowerCase().includes(search.value.toLowerCase())));
const hasFilters=computed(()=>!!search.value.trim()||filter.value!=='all'),emptyState=computed(()=>releaseListEmptyState(items.value.length,hasFilters.value,kind.value));
const selectedPreview=computed(()=>selected.value?.datasetPreview);
const listGroups=computed(()=>kind.value==='snapshots'?[{key:'snapshots',title:'工作快照',items:visible.value}]:[{key:'published',title:'当前发布',items:visible.value.filter(item=>item.status==='published')},{key:'candidates',title:'待发布候选',items:visible.value.filter(item=>item.status!=='published')}]);
const creating=ref(false),editingId=ref(''),version=ref(''),title=ref(''),notes=ref(''),sourceRef=ref(props.branch),dialog=ref<HTMLElement>();
const formError=ref(''),formBaseline=ref(''),formPreview=ref<DatasetReleasePreview>(),formPreviewLoading=ref(false),formPreviewError=ref(''),lastGenerated=ref(''),savingStage=ref<'save'|'build'>('save');
const snapshotOpen=ref(false),snapshotAcknowledged=ref(false),snapshotError=ref(''),snapshotDialog=ref<HTMLElement>();
const errataOpen=ref(false),errataDraft=ref(''),shares=ref<ReleaseShare[]>([]),shareDays=ref('7'),shareAssetId=ref(''),shareLink=ref(''),showSharing=ref(false),showAudit=ref(false),shareNotice=ref('');
const unknownWrite=ref<{message:string;operationId?:string;shareId?:string;cause:ApiError}>();
const writeLocked=computed(()=>busy.value||!!unknownWrite.value),shareAssets=computed(()=>shareableReleaseAssets(selected.value));
const suggestions=computed(()=>releaseFormSuggestions(items.value,decodeURIComponent(props.base.split('/').at(-1)??'dataset'),props.branch));
const formValue=()=>JSON.stringify([version.value,title.value,notes.value,sourceRef.value]);
const releaseFormDirty=computed(()=>creating.value&&formValue()!==formBaseline.value),formDirty=computed(()=>releaseFormDirty.value||!!errataDraft.value.trim()||snapshotOpen.value);
const notesCustomized=computed(()=>!!lastGenerated.value&&notes.value!==lastGenerated.value);
const releaseStep=computed(()=>selected.value?.status==='published'?3:selected.value?.status==='ready'?2:['queued','building'].includes(selected.value?.status??'')?1:0);
const localLink=computed(()=>{try{return ['127.0.0.1','localhost','::1','[::1]'].includes(new URL(shareLink.value).hostname);}catch{return false;}});
const label=(status:string,itemKind:DatasetRelease['kind']='release')=>itemKind==='snapshot'&&status==='ready'?'可下载':({draft:'草稿',queued:'排队中',building:'打包中',ready:'待发布核对',published:'已发布',failed:'打包失败'}[status]??status);
const timestamp=(value?:string)=>value?new Date(value).toLocaleString('zh-CN',{hour12:false}):'—';
const bytes=(value:number)=>value<1024?value+' B':value<1024*1024?(value/1024).toFixed(1)+' KiB':(value/1024/1024).toFixed(1)+' MiB';
const assetName=(asset:ReleaseAsset)=>asset.kind==='manifest'?'版本清单':asset.audience==='internal'?'受权内部数据包':'数据集发布包';
let disposed=false,internalNavigation=0,previewGeneration=0,poll:ReturnType<typeof setTimeout>|undefined,previewTimer:ReturnType<typeof setTimeout>|undefined;
let previousFocus:HTMLElement|null=null,snapshotPreviousFocus:HTMLElement|null=null;
const viewContext=()=>JSON.stringify([credentialContext(app.status?.identity),props.base,kind.value]);
const selectionContext=()=>JSON.stringify([viewContext(),selectedId.value]);
const actionScope=createReleaseRequestScope(selectionContext),saveScope=createReleaseRequestScope(viewContext),saver=createReleaseCandidateSaver();
function retain(saved:DatasetRelease){listReader.invalidate();items.value=retainReleaseResult(items.value,saved);}
function acceptList(value:ReleaseList){
  const next=value.items;
  items.value=next;capabilities.value=value.capabilities;readbackNotice.value='';
  if(selectedId.value&&!next.some(item=>item.id===selectedId.value))selectedId.value='';
}
const listReader=createReleaseReader<ReleaseList>({context:viewContext,request:()=>request(props.base+'/'+kind.value),accept:acceptList});
const loading=listReader.loading,listError=listReader.error;
const shareReader=createReleaseReader<ReleaseShare[]>({context:()=>JSON.stringify([selectionContext(),showSharing.value]),request:()=>request(props.base+'/releases/'+selectedId.value+'/shares'),accept:value=>{shares.value=value;shareNotice.value='';}});
const sharesLoading=shareReader.loading,sharesError=shareReader.error;
function clearActionFeedback(){error.value='';actionNotice.value='';}
function lockUnknown(cause:unknown,shareId?:string){if(isUnknownOperationError(cause))unknownWrite.value={message:cause.message,operationId:cause.operationId,shareId,cause};}
function reportAction(cause:unknown){error.value=(cause as Error).message;lockUnknown(cause);}
async function load(quiet=false){clearTimeout(poll);const result=await listReader.read();if(!result.ok||disposed)return result;if(items.value.some(item=>['queued','building'].includes(item.status)))poll=setTimeout(()=>void load(true),1500);return result;}
async function refreshAfterWrite(){const result=await load(true);if(result&&!result.ok&&!('stale'in result))readbackNotice.value='操作已完成，但列表刷新失败。当前保留已确认的结果；重试刷新只读取数据，不会重复提交。';}
async function recheckUnknown(){const current=actionScope.capture(),pending=unknownWrite.value,item=selected.value;if(pending?.shareId&&item){const base=props.base,id=pending.shareId;const outcome=await verifyDeletion(pending.cause,{readCurrent:()=>request<ReleaseShare[]>(base+'/releases/'+item.id+'/shares'),isRemoved:values=>!values.some(value=>value.id===id&&!value.revokedAt),isCurrent:current});if(!current())return;if(outcome.current)shares.value=outcome.current;if(outcome.state==='confirmed'){unknownWrite.value=undefined;error.value='';actionNotice.value='已从最新状态核对：该链接当前已撤销或不存在。';}return;}await load(true);}
function hint(field:'version'|'title'|'sourceRef',event?:KeyboardEvent){if(event&&!canAcceptReleaseHint(event))return;const fields={version,title,sourceRef};fields[field].value=acceptReleaseHint(fields[field].value,suggestions.value[field]);}
async function discardErratum(){if(errataDraft.value.trim()&&!await app.confirmAction('当前勘误尚未保存，确认放弃并切换吗？',{title:'未保存的勘误',confirmLabel:'放弃并切换'}))return false;errataDraft.value='';errataOpen.value=false;return true;}
async function replaceSelection(release:string|undefined,releaseKind=kind.value){internalNavigation++;try{await router.replace({query:{...route.query,release,releaseKind}});}finally{internalNavigation--;}}
async function choose(item:DatasetRelease,afterWrite=false){if(busy.value&&!afterWrite||!await discardErratum())return;selectedId.value=item.id;await replaceSelection(item.id);}
async function switchKind(value:'releases'|'snapshots'){if(busy.value||value===kind.value||!await discardErratum())return;kind.value=value;filter.value='all';await replaceSelection(undefined,value);}
async function backList(){if(busy.value||!await discardErratum())return;selectedId.value='';await replaceSelection(undefined);}
function clearFilters(){search.value='';filter.value='all';}
async function loadFormPreview(){clearTimeout(previewTimer);const operation=++previewGeneration,current=saveScope.capture(),base=props.base;if(!creating.value||!sourceRef.value.trim()){formPreviewLoading.value=false;return;}formPreviewError.value='';formPreviewLoading.value=true;try{const value=await post<DatasetReleasePreview>(base+'/releases/preview',{sourceRef:sourceRef.value.trim()});if(operation!==previewGeneration||!current()||disposed||!creating.value)return;const wasClean=!releaseFormDirty.value;formPreview.value=value;notes.value=refreshedReleaseNotes(notes.value,lastGenerated.value,value.generatedNotes);lastGenerated.value=value.generatedNotes;if(wasClean)formBaseline.value=formValue();}catch(cause){if(operation===previewGeneration&&current())formPreviewError.value=(cause as Error).message;}finally{if(operation===previewGeneration&&current())formPreviewLoading.value=false;}}
async function openCreate(item?:DatasetRelease){if(writeLocked.value||!await discardErratum())return;previousFocus=document.activeElement as HTMLElement;editingId.value=item?.id??'';version.value=item?.version??'';title.value=item?.title??'';notes.value=item?.notes??'';lastGenerated.value=item?.generatedNotes??'';sourceRef.value=item?.sourceRef??props.branch;formError.value='';formPreviewError.value='';formPreview.value=undefined;formBaseline.value=formValue();creating.value=true;await nextTick();dialog.value?.querySelector<HTMLInputElement>('input')?.focus();void loadFormPreview();}
async function closeCreate(){if(busy.value)return;if(releaseFormDirty.value&&!await app.confirmAction('当前发布表单尚未保存，确认关闭吗？',{title:'未保存的发布草稿',confirmLabel:'放弃表单'}))return;creating.value=false;clearTimeout(previewTimer);previewGeneration++;formPreviewLoading.value=false;previousFocus?.focus();}
async function regenerateNotes(){if(formPreviewLoading.value||!formPreview.value)return;if(notesCustomized.value&&!await app.confirmAction('用当前比较结果替换已编辑的说明？',{title:'重新采用自动说明',confirmLabel:'替换说明'}))return;notes.value=formPreview.value.generatedNotes;lastGenerated.value=formPreview.value.generatedNotes;}
async function save(validate=true){
  if(writeLocked.value)return;formError.value='';const preview=formPreview.value;
  if(formPreviewLoading.value||!preview||formPreviewError.value||!preview.ok){formError.value=formPreviewError.value||'请先完成当前来源版本的发布检查。';return;}
  const current=saveScope.capture(),base=props.base,context=viewContext(),existing=editingId.value?items.value.find(item=>item.id===editingId.value):undefined;
  if(editingId.value&&!existing){formError.value='发布候选已变化，请刷新后核对。';return;}
  const input={version:version.value.trim(),title:title.value.trim(),notes:notes.value,sourceRef:sourceRef.value.trim(),expectedCommit:preview.commitId,expectedBaselineReleaseId:preview.baselineReleaseId,expectedPlanDigest:preview.planDigest};
  busy.value=true;savingStage.value='save';clearActionFeedback();
  try{const outcome=await saver.save({context,current,write:()=>existing?patch(base+'/releases/'+existing.id,{...input,expectedRevision:existing.revision}):post(base+'/releases',input),accept:saved=>{retain(saved);editingId.value=saved.id;formBaseline.value=formValue();},...(validate?{build:(saved:DatasetRelease)=>{savingStage.value='build';return post<DatasetRelease>(base+'/releases/'+saved.id+'/build',{expectedRevision:saved.revision});}}:{})});
    if(outcome.state==='busy'){if(current())formError.value='此项目先前的保存仍在处理中，请等待结果后再保存；当前输入继续保留，可只读刷新核对。';return;}
    if(outcome.state==='stale'||!current())return;
    creating.value=false;await choose(outcome.value,true);if(!current())return;await refreshAfterWrite();if(!current())return;
    if(outcome.state==='build-failed'){reportAction(outcome.error);actionNotice.value='候选已保存，校验打包未确认完成。当前候选保留，无需重新创建。';}
    else actionNotice.value=outcome.state==='queued'?'候选已保存并开始校验打包；完成后请核对并发布。':'发布候选已保存，可稍后校验打包。';
    app.notify(actionNotice.value);
  }catch(cause){if(current()){formError.value=(cause as Error).message;lockUnknown(cause);if(cause instanceof ApiError&&cause.code==='RELEASE_PREVIEW_CHANGED')void loadFormPreview();}}
  finally{if(context===viewContext())busy.value=false;}
}
async function run(action:'build'|'publish'|'withdraw',item:DatasetRelease){
  if(writeLocked.value)return;const current=actionScope.capture(),base=props.base,context=viewContext();
  if(action==='publish'&&!await app.confirmAction(`发布 ${item.version} 将替换现有已发布版本，并让旧下载链接和分享链接失效。每个项目只保留一个当前发布；分支和提交历史不受影响。新版本固定提交 ${item.commitId.slice(0,12)}，请核对内容和接收对象。`,{title:'发布此版本',confirmLabel:'正式发布'}))return;
  if(action==='withdraw'&&!await app.confirmAction(`撤回 ${item.version} 后，将移除当前发布及其文件，下载和分享链接失效；项目将暂无当前发布，分支及提交历史保留。`,{title:'撤回 Release',confirmLabel:'撤回版本'}))return;
  if(!current()||writeLocked.value)return;busy.value=true;clearActionFeedback();
  try{const result=await post<DatasetRelease|{removedReleaseId:string}>(base+'/'+(item.kind==='snapshot'?'snapshots':'releases')+'/'+item.id+'/'+action,{expectedRevision:item.revision});if(!current())return;
    if('removedReleaseId'in result){listReader.invalidate();items.value=items.value.filter(value=>value.id!==result.removedReleaseId);selectedId.value='';await replaceSelection(undefined);}else retain(result);
    actionNotice.value='status'in result&&releaseCleanupWarning(result)|| (action==='build'?'完整数据集打包任务已排队':action==='publish'?'新版已发布，旧下载链接已失效':'当前发布已撤回');
    await refreshAfterWrite();if(context===viewContext()&&!disposed)app.notify(actionNotice.value);
  }catch(cause){if(current())reportAction(cause);}finally{if(context===viewContext())busy.value=false;}
}
async function openSnapshot(){if(!capabilities.value.export||writeLocked.value||!await discardErratum())return;snapshotAcknowledged.value=false;snapshotError.value='';snapshotOpen.value=true;}
async function newSnapshot(){if(writeLocked.value||!snapshotAcknowledged.value)return;const current=saveScope.capture(),base=props.base,identity=credentialContext(app.status?.identity);busy.value=true;snapshotError.value='';clearActionFeedback();try{const saved=await post<DatasetRelease>(base+'/snapshots',{ref:props.branch});if(!current())return;snapshotOpen.value=false;kind.value='snapshots';busy.value=true;const context=viewContext();await nextTick();if(context!==viewContext()||disposed)return;retain(saved);await choose(saved,true);if(context!==viewContext()||disposed)return;await refreshAfterWrite();if(context!==viewContext()||disposed)return;actionNotice.value='完整工作快照打包已排队，未提交草稿不包含在内。';app.notify(actionNotice.value);}catch(cause){if(current()){snapshotError.value=(cause as Error).message;lockUnknown(cause);}}finally{if(base===props.base&&identity===credentialContext(app.status?.identity))busy.value=false;}}
async function saveErratum(){const item=selected.value;if(!item||!errataDraft.value.trim()||writeLocked.value)return;const current=actionScope.capture(),base=props.base,context=viewContext(),body=errataDraft.value;busy.value=true;clearActionFeedback();try{const saved=await post<DatasetRelease>(base+'/releases/'+item.id+'/errata',{expectedRevision:item.revision,body});if(!current())return;retain(saved);errataDraft.value='';errataOpen.value=false;actionNotice.value='勘误已追加并留痕。';await refreshAfterWrite();}catch(cause){if(current())reportAction(cause);}finally{if(context===viewContext())busy.value=false;}}
async function loadShares(){if(!selected.value)return;showSharing.value=!showSharing.value;if(showSharing.value)await shareReader.read();else shareReader.reset();}
async function createShare(){const item=selected.value;if(!item||writeLocked.value||!shareAssets.value.some(asset=>asset.id===shareAssetId.value))return;const current=actionScope.capture(),base=props.base,context=viewContext(),assetId=shareAssetId.value,expiresAt=new Date(Date.now()+Number(shareDays.value)*86400_000).toISOString();busy.value=true;clearActionFeedback();shareLink.value='';try{const value=await post<ReleaseShare&{downloadPath:string}>(base+'/releases/'+item.id+'/shares',{assetId,expiresAt});if(!current())return;shareReader.invalidate();shares.value=[value,...shares.value.filter(share=>share.id!==value.id)];shareLink.value=window.location.origin+value.downloadPath;const refreshed=await shareReader.read();if(!current())return;if(!refreshed.ok)shareNotice.value='链接已创建，列表刷新失败。请保存下方仅显示一次的链接；重试仅刷新列表。';else shareNotice.value='下载链接已创建，请保存下方仅显示一次的链接。';await refreshAfterWrite();}catch(cause){if(current())reportAction(cause);}finally{if(context===viewContext())busy.value=false;}}
async function revoke(share:ReleaseShare){
  const item=selected.value;if(!item||writeLocked.value)return;
  const current=actionScope.capture(),base=props.base,context=viewContext();
  if(!await app.confirmAction('撤销此下载链接？已下载副本不会收回。',{title:'撤销分享链接',confirmLabel:'撤销链接'})||!current()||writeLocked.value)return;
  busy.value=true;clearActionFeedback();
  try{const outcome=await removeAndVerify<ReleaseShare[]>(base+'/releases/'+item.id+'/shares/'+share.id,{readCurrent:()=>request(base+'/releases/'+item.id+'/shares'),isRemoved:values=>!values.some(value=>value.id===share.id&&!value.revokedAt),isCurrent:current});
    if(!current())return;
    if(outcome.current)shares.value=outcome.current;
    if(outcome.state==='unknown'){error.value=outcome.error.message;lockUnknown(outcome.error,share.id);return;}
    if(outcome.via==='response'){shareReader.invalidate();const saved={...share,revokedAt:new Date().toISOString()};shares.value=shares.value.map(value=>value.id===saved.id?saved:value);}
    shareLink.value='';actionNotice.value=outcome.via==='read'?'已从最新状态核对：该链接当前已撤销或不存在。':'下载链接已撤销。';
    if(!outcome.current){const result=await shareReader.read();if(current()&&!result.ok)shareNotice.value='链接已撤销，但列表刷新失败；当前保留已确认结果。';}
  }catch(cause){if(current())reportAction(cause);}finally{if(context===viewContext())busy.value=false;}
}
async function copyLink(){const current=actionScope.capture(),value=shareLink.value;try{await navigator.clipboard.writeText(value);if(current())app.notify('分享链接已复制');}catch{if(current())app.notify('请选中文本手动复制。');}}
const allowLeave=async()=>internalNavigation>0||!busy.value&&(!formDirty.value||await app.confirmAction('当前发布表单、快照或勘误尚未完成，确认离开吗？',{title:'未保存的发布输入',confirmLabel:'放弃并离开'}));
const unregister=app.registerDraftGuard(allowLeave);onBeforeRouteLeave(allowLeave);onBeforeRouteUpdate((to,from)=>(['namespace','repo','tab'].some(key=>to.params[key]!==from.params[key])||to.query.release!==from.query.release||to.query.releaseKind!==from.query.releaseKind)?allowLeave():true);
function beforeUnload(event:BeforeUnloadEvent){if(formDirty.value||busy.value){event.preventDefault();event.returnValue='';}}
watch(()=>sourceRef.value,()=>{formPreview.value=undefined;previewGeneration++;formPreviewLoading.value=false;clearTimeout(previewTimer);if(creating.value)previewTimer=setTimeout(()=>void loadFormPreview(),350);});
watch(snapshotOpen,async value=>{if(value){snapshotPreviousFocus=document.activeElement as HTMLElement;await nextTick();snapshotDialog.value?.querySelector<HTMLInputElement>('input')?.focus();}else snapshotPreviousFocus?.focus();});
watch(selectionContext,()=>{actionScope.invalidate();shareReader.reset();shares.value=[];shareLink.value='';shareAssetId.value='';shareNotice.value='';showSharing.value=false;showAudit.value=false;error.value='';actionNotice.value='';unknownWrite.value=undefined;},{flush:'sync'});
watch(()=>[route.query.release,route.query.releaseKind],()=>{selectedId.value=typeof route.query.release==='string'?route.query.release:'';kind.value=route.query.releaseKind==='snapshots'?'snapshots':'releases';});
watch(viewContext,(value,previous)=>{saveScope.invalidate();listReader.reset();clearTimeout(poll);items.value=[];filter.value='all';readbackNotice.value='';error.value='';actionNotice.value='';unknownWrite.value=undefined;busy.value=false;if(previous&&JSON.parse(value)[0]!==JSON.parse(previous)[0]||previous&&JSON.parse(value)[1]!==JSON.parse(previous)[1]){creating.value=false;errataDraft.value='';previewGeneration++;formPreview.value=undefined;}selectedId.value=route.query.releaseKind===kind.value&&typeof route.query.release==='string'?route.query.release:'';void load();},{flush:'sync'});
onMounted(()=>{void load();window.addEventListener('beforeunload',beforeUnload);});onBeforeUnmount(()=>{disposed=true;saveScope.invalidate();actionScope.invalidate();listReader.reset();shareReader.reset();previewGeneration++;clearTimeout(poll);clearTimeout(previewTimer);unregister();window.removeEventListener('beforeunload',beforeUnload);});
</script>

<template>
<section class="releases-page">
<header class="release-page-heading"><div><span class="release-eyebrow"><Package :size="15"/>完整数据集交付</span><h2>Releases</h2><p>核对已提交的数据，发布后替换上一版。</p></div><div><button v-if="capabilities.export" class="btn" :disabled="writeLocked" @click="openSnapshot"><Download :size="15"/>导出工作快照</button><button v-if="capabilities.manage&&kind==='releases'" class="btn btn-primary" :disabled="writeLocked" @click="openCreate()"><Plus :size="16"/>创建 Release</button></div></header>
<details class="release-scope-help"><summary><ShieldCheck :size="14"/>发布与导出规则</summary><p>发布选定提交的整份数据集，字段遵循“是否导出”设置。业务字段不筛除样本或分组；未提交草稿不包含在内。工作快照仅内部核对，不代表专家复核或正式发布。</p></details>
<div class="release-view-tabs"><button :class="{active:kind==='releases'}" @click="switchKind('releases')">项目 Releases</button><button v-if="capabilities.export" :class="{active:kind==='snapshots'}" @click="switchKind('snapshots')">我的工作快照</button><button class="btn btn-ghost release-refresh" aria-label="刷新发布列表" :disabled="loading||busy" @click="load()"><RefreshCw :size="14"/></button></div><p v-if="listError" class="error-state" role="alert">列表读取失败：{{listError}} <button class="btn" :disabled="loading" @click="load()">重试刷新</button></p><p v-if="error" class="error-state" role="alert">{{error}} <button class="btn btn-ghost" type="button" @click="error=''">关闭提示</button></p><p v-if="actionNotice" class="notice release-action-notice" role="status">{{actionNotice}}</p><p v-if="readbackNotice" class="notice" role="status">{{readbackNotice}} <button class="btn" :disabled="loading" @click="load()">只读重试刷新</button></p><section v-if="unknownWrite&&!creating&&!snapshotOpen" class="notice release-unknown" role="alert"><strong>操作结果待核对</strong><p>{{unknownWrite.message}} 输入与已确认结果仍保留，未再次提交。</p><button class="btn" :disabled="loading||sharesLoading" @click="recheckUnknown">只读核对状态</button><a v-if="unknownWrite.operationId" :href="'/operations?operation='+encodeURIComponent(unknownWrite.operationId)" target="_blank" rel="noopener" class="btn">打开操作核对（新窗口）</a></section><div v-if="loading&&!items.length" class="empty" role="status"><LoaderCircle class="spin" :size="24"/>正在读取固定版本…</div>
<template v-else-if="!selected"><div class="release-search"><label class="search-field"><Search :size="16"/><input v-model="search" aria-label="搜索发布版本" placeholder="搜索版本号或标题"/></label><select v-model="filter" aria-label="筛选发布状态"><option value="all">全部状态</option><template v-if="kind==='releases'"><option value="published">当前发布</option><option value="drafts">待发布候选</option></template><template v-else><option value="ready">可下载快照</option><option value="processing">待完成或失败</option></template></select></div><div v-if="!visible.length&&!listError" class="panel release-empty"><Package :size="38"/><h3>{{emptyState.title}}</h3><p>{{emptyState.clear?'调整搜索或状态条件，已保存的版本仍然保留。':kind==='snapshots'?'导出已提交的完整数据集用于内部核对。':'选择已提交版本，检查变更说明后发布完整数据集。'}}</p><button v-if="emptyState.clear" class="btn" @click="clearFilters">清除筛选</button><button v-if="emptyState.create&&capabilities.manage&&kind==='releases'" class="btn btn-primary" :disabled="writeLocked" @click="openCreate()">创建第一个 Release</button></div><template v-for="group in listGroups" :key="group.key"><h3 v-if="group.items.length" class="release-group-title">{{group.title}}</h3><button v-for="item in group.items" :key="item.id" class="release-list-item" @click="choose(item)"><span class="release-marker"><Package :size="20"/></span><div class="release-item-main"><div><strong>{{item.title}}</strong><span class="release-status" :class="item.status">{{label(item.status,item.kind)}}</span><span v-if="item.status==='published'" class="release-chip latest">当前发布</span></div><p><code>{{item.version}}</code><span>{{item.createdBy.name}} · {{timestamp(item.createdAt)}}</span></p><p class="release-list-notes">{{item.notes}}</p><footer><code>{{item.commitId.slice(0,12)}}</code><span>{{item.rowCount?.toLocaleString()??'—'}} 条样本</span><span>{{item.assets.length}} 项资产</span></footer></div><ArrowUpRight :size="17"/></button></template></template>
<article v-else class="release-detail"><button class="release-back" @click="backList"><ArrowLeft :size="15"/>返回版本列表</button><header class="release-detail-heading"><div><div class="release-detail-badges"><code>{{selected.version}}</code><span class="release-status" :class="selected.status">{{label(selected.status,selected.kind)}}</span><span v-if="selected.status==='published'" class="release-chip latest">当前发布</span></div><h2>{{selected.title}}</h2><p>{{selected.createdBy.name}} · {{timestamp(selected.createdAt)}}</p></div><div class="release-detail-actions"><button v-if="capabilities.manage&&selected.kind==='release'&&['draft','failed','ready'].includes(selected.status)" class="btn" :disabled="writeLocked" @click="openCreate(selected)">编辑发布候选</button><button v-if="((selected.kind==='release'&&capabilities.manage)||(selected.kind==='snapshot'&&capabilities.export))&&['draft','failed','ready'].includes(selected.status)" :class="selected.status==='ready'?'btn':'btn btn-primary'" :disabled="writeLocked" @click="run('build',selected)"><Package :size="15"/>{{selected.status==='ready'?'重新校验打包':'校验并打包'}}</button><button v-if="capabilities.manage&&selected.kind==='release'&&selected.status==='ready'" class="btn btn-primary" :disabled="writeLocked" @click="run('publish',selected)"><CheckCircle2 :size="15"/>核对并发布</button><button v-if="capabilities.manage&&selected.status==='published'" class="btn btn-ghost" :disabled="writeLocked" @click="run('withdraw',selected)">撤回</button></div></header>
<WorkflowSteps v-if="selected.kind==='release'" :steps="['固定版本与说明','校验打包','核对发布','已发布版本']" :current="releaseStep" label="发布步骤"/>
<p v-if="releaseCleanupWarning(selected)" class="notice release-cleanup-warning" role="alert">{{releaseCleanupWarning(selected)}}</p><div class="release-content-grid"><div class="release-body"><p v-if="selected.kind==='snapshot'" class="notice">内部工作快照，不代表正式发布或专家复核。</p><div v-if="['queued','building'].includes(selected.status)" class="release-build-state" role="status"><LoaderCircle class="spin" :size="22"/><div><strong>{{label(selected.status,selected.kind)}}</strong><p>数据提交 {{selected.commitId.slice(0,12)}} 与比较基线已固定。</p></div></div><div v-if="selected.error" class="error-state" role="alert"><strong>{{selected.error}}</strong><ul v-if="selected.issues.length"><li v-for="issue in selected.issues" :key="issue">{{issue}}</li></ul></div>
<section v-if="selectedPreview" class="panel release-summary"><header><h3>数据与变更</h3><code>{{selectedPreview.commitId.slice(0,12)}}</code></header><div class="release-summary-stats"><span>样本<strong>{{selectedPreview.rowCount.toLocaleString()}}</strong></span><span>附件<strong>{{selectedPreview.attachmentCount.toLocaleString()}}</strong></span><span>导出字段<strong>{{selectedPreview.includedFields.length}}</strong></span></div><p>比较基线：{{selectedPreview.baselineVersion??'首个正式版本'}}<code v-if="selectedPreview.baselineCommitId"> · {{selectedPreview.baselineCommitId.slice(0,12)}}</code></p><div v-if="selectedPreview.comparison" class="release-summary-stats"><span>样本新增<strong>+{{selectedPreview.comparison.samples.added}}</strong></span><span>修改<strong>{{selectedPreview.comparison.samples.modified}}</strong></span><span>删除<strong>−{{selectedPreview.comparison.samples.removed}}</strong></span></div><div class="release-summary-stats"><span>文件新增<strong>+{{selectedPreview.changes.files.added}}</strong></span><span>修改<strong>{{selectedPreview.changes.files.modified}}</strong></span><span>删除<strong>−{{selectedPreview.changes.files.removed}}</strong></span></div><p v-for="warning in selectedPreview.warnings" :key="warning" class="notice">{{warning}}</p></section>
<section class="panel release-notes"><header><h3>版本说明</h3><span>受限 Markdown</span></header><ReleaseMarkdown :source="selected.notes"/><details v-if="selected.generatedNotes&&selected.generatedNotes!==selected.notes" class="release-generated-notes"><summary>查看生成时的变更记录</summary><ReleaseMarkdown :source="selected.generatedNotes"/></details><section v-if="selected.errata?.length" class="release-errata"><h4>发布后勘误</h4><article v-for="entry in selected.errata" :key="entry.id"><p>{{entry.actor.name}} · {{timestamp(entry.createdAt)}}</p><ReleaseMarkdown :source="entry.body"/></article></section><div v-if="capabilities.manage&&selected.kind==='release'&&['published','withdrawn'].includes(selected.status)" class="release-erratum-editor"><button class="btn btn-ghost" :disabled="writeLocked" @click="errataOpen=!errataOpen">{{errataOpen?'收起':'添加发布后勘误'}}</button><form v-if="errataOpen" @submit.prevent="saveErratum"><label class="field">补充说明<textarea v-model="errataDraft" rows="4" maxlength="10000"/></label><button class="btn" :disabled="writeLocked||!errataDraft.trim()">追加勘误并留痕</button></form></div></section>
<section class="panel release-assets"><header><h3><FileArchive :size="17"/>发布产物 <span>{{selected.assets.length}}</span></h3><span>固定 checksum</span></header><div v-if="!selected.assets.length" class="empty">{{selected.status==='failed'?'打包失败，没有可下载资产。':'打包完成后提供固定数据集与清单。'}}</div><div v-for="asset in selected.assets" :key="asset.id" class="release-asset"><FileArchive :size="18"/><div><a v-if="selected.status!=='withdrawn'" :href="'/api'+base+'/'+kind+'/'+selected.id+'/assets/'+asset.id" download>{{asset.name}}<Download :size="14"/></a><strong v-else>{{asset.name}}</strong><p class="release-asset-audience"><span>{{assetName(asset)}}</span></p><code>SHA-256 {{asset.sha256}}</code></div><span>{{bytes(asset.size)}}</span></div></section>
<section v-if="capabilities.share&&selected.kind==='release'&&selected.status==='published'" class="panel release-share"><header><h3><Share2 :size="16"/>固定资产分享</h3><button class="btn btn-ghost" :disabled="sharesLoading" @click="loadShares">{{showSharing?'收起':'管理下载链接'}}</button></header><div v-if="showSharing"><p v-if="sharesLoading" class="release-help" role="status">正在读取下载链接…</p><p v-if="sharesError" class="error-state" role="alert">下载链接读取失败：{{sharesError}} <button class="btn" :disabled="sharesLoading" @click="shareReader.read()">只读重试</button></p><p v-if="shareNotice" class="notice" role="status">{{shareNotice}}</p><div class="share-create"><label>分享资产<select v-model="shareAssetId" aria-label="选择可共享发布资产"><option value="">请选择资产</option><option v-for="asset in shareAssets" :key="asset.id" :value="asset.id">{{asset.name}} · {{assetName(asset)}}</option></select></label><label>有效期<select v-model="shareDays"><option value="1">1天</option><option value="7">7天</option><option value="30">30天</option></select></label><button class="btn" :disabled="writeLocked||!shareAssetId||!shareAssets.some(asset=>asset.id===shareAssetId)" @click="createShare"><Plus :size="14"/>创建下载链接</button></div><p v-if="!shareAssets.length" class="release-help">此版本没有允许外链分享的资产。</p><div v-if="shareLink" class="created-share"><input :value="shareLink" readonly aria-label="刚创建的分享链接" @focus="($event.target as HTMLInputElement).select()"/><button class="btn" @click="copyLink"><Copy :size="14"/>复制</button><p v-if="localLink">当前地址只在本机可达；对外分发需要实际可达的受控部署地址。</p><p>链接令牌仅创建时显示一次，请勿写入公开文档或日志。</p></div><div v-for="share in shares" :key="share.id" class="share-row"><div><strong>{{share.revokedAt?'已撤销':Date.parse(share.expiresAt)<=Date.now()?'已过期':'有效'}}</strong><span>资产：{{selected.assets.find(asset=>asset.id===share.assetId)?.name??'固定资产'}}</span><span>{{share.createdBy.name}} · {{timestamp(share.expiresAt)}}</span></div><button v-if="!share.revokedAt&&Date.parse(share.expiresAt)>Date.now()" class="btn btn-ghost" :disabled="writeLocked" @click="revoke(share)"><Trash2 :size="14"/>撤销</button></div></div></section>
</div><aside class="panel release-facts"><h3>版本信息</h3><dl><dt>固定提交</dt><dd><code>{{selected.commitId}}</code><button v-if="capabilities.hidden" class="btn btn-ghost" @click="emit('open-version',selected.commitId)">查看只读数据<ArrowUpRight :size="13"/></button></dd><dt>来源分支／版本</dt><dd>{{selected.sourceRef}}</dd><dt>比较基线</dt><dd>{{selectedPreview?.baselineVersion??'—'}}</dd><dt>样本数</dt><dd>{{selected.rowCount?.toLocaleString()??selectedPreview?.rowCount.toLocaleString()??'—'}}</dd><dt>创建</dt><dd>{{timestamp(selected.createdAt)}}</dd><dt>发布</dt><dd>{{timestamp(selected.publishedAt)}}</dd></dl><button class="btn btn-ghost" @click="showAudit=!showAudit"><History :size="14"/>{{showAudit?'收起':'查看'}}操作记录</button><ol v-if="showAudit" class="release-audit"><li v-for="(entry,index) in selected.audit" :key="index"><strong>{{entry.action}}</strong><span>{{entry.actor.name}} · {{timestamp(entry.at)}}{{entry.detail?' · '+entry.detail:''}}</span></li></ol></aside></div></article>

<div v-if="creating" class="modal-backdrop release-dialog-backdrop" @click.self="closeCreate"><section ref="dialog" class="release-dialog" role="dialog" aria-modal="true" aria-labelledby="release-dialog-title" @keydown="releaseDialogKey" @keydown.esc.stop.prevent="closeCreate"><header><div><h2 id="release-dialog-title">{{editingId?'编辑发布候选':'创建 Release'}}</h2><p>核对数据与变更，自动说明可以直接编辑。</p></div><button type="button" class="icon-button" :disabled="busy" aria-label="关闭发布表单" @click="closeCreate"><X :size="19"/></button></header><form @submit.prevent="save(true)"><fieldset :disabled="writeLocked"><div class="release-form-grid"><label class="field">版本号<input v-model="version" required maxlength="80" pattern="[a-zA-Z0-9][a-zA-Z0-9._-]{0,79}" :placeholder="suggestions.version" @keydown="hint('version',$event)"/><small>空值按 Tab 采用建议。</small></label><label class="field">来源分支／提交<input v-model="sourceRef" required maxlength="160" :placeholder="suggestions.sourceRef" @keydown="hint('sourceRef',$event)"/></label></div><label class="field">版本标题<input v-model="title" required maxlength="240" :placeholder="suggestions.title" @keydown="hint('title',$event)"/></label>
<section class="release-form-summary" aria-label="发布检查与自动说明"><header><div><h3>数据与变更检查</h3><code v-if="formPreview" class="release-preview-commit">提交 {{formPreview.commitId.slice(0,12)}}</code></div><button class="btn btn-ghost" type="button" :disabled="formPreviewLoading||busy||!sourceRef.trim()" @click="loadFormPreview"><RefreshCw :size="14"/>重新检查</button></header><p v-if="formPreviewLoading" class="release-help" role="status"><LoaderCircle class="spin" :size="14"/>正在固定数据提交并比较上一正式版本…</p><p v-if="formPreviewError" class="error-state" role="alert">{{formPreviewError}}</p><template v-if="formPreview"><div class="release-summary-stats"><span>样本<strong>{{formPreview.rowCount.toLocaleString()}}</strong></span><span>附件<strong>{{formPreview.attachmentCount.toLocaleString()}}</strong></span><span>导出字段<strong>{{formPreview.includedFields.length}}</strong></span></div><p>比较基线：<strong>{{formPreview.baselineVersion??'首个正式版本'}}</strong><code v-if="formPreview.baselineCommitId"> · {{formPreview.baselineCommitId.slice(0,12)}}</code></p><div v-if="formPreview.comparison" class="release-summary-stats"><span>样本新增<strong>+{{formPreview.comparison.samples.added}}</strong></span><span>修改<strong>{{formPreview.comparison.samples.modified}}</strong></span><span>删除<strong>−{{formPreview.comparison.samples.removed}}</strong></span></div><div class="release-summary-stats"><span>文件新增<strong>+{{formPreview.changes.files.added}}</strong></span><span>修改<strong>{{formPreview.changes.files.modified}}</strong></span><span>删除<strong>−{{formPreview.changes.files.removed}}</strong></span></div><p v-if="formPreview.excludedFields.length">未导出字段：{{formPreview.excludedFields.join('、')}}</p><p v-for="warning in formPreview.warnings" :key="warning" class="notice">{{warning}}</p><ul v-if="formPreview.issues.length" class="error-state"><li v-for="issue in formPreview.issues" :key="issue">{{issue}}</li></ul></template></section>
<div class="release-notes-label"><label for="release-notes">版本说明</label><button class="btn btn-ghost" type="button" :disabled="busy||formPreviewLoading||!formPreview" @click="regenerateNotes"><RefreshCw :size="13"/>重新采用自动说明</button></div><textarea id="release-notes" v-model="notes" class="release-notes-input" rows="8" maxlength="30000" placeholder="数据检查完成后自动生成变更说明，可直接编辑。"/><p class="release-help">{{notesCustomized?'已保留你编辑的说明。重新检查不会覆盖它，可显式重新采用自动说明。':'自动说明在本机生成，可直接补充。'}}</p></fieldset><p v-if="formError" class="error-state" role="alert">{{formError}}</p><section v-if="unknownWrite" class="notice release-unknown" role="alert"><strong>操作结果待核对</strong><p>{{unknownWrite.message}} 当前输入保留，未重复提交。</p><button type="button" class="btn" :disabled="loading" @click="recheckUnknown">只读核对状态</button><a v-if="unknownWrite.operationId" :href="'/operations?operation='+encodeURIComponent(unknownWrite.operationId)" target="_blank" rel="noopener" class="btn">打开操作核对（新窗口）</a></section><footer><button class="btn btn-ghost" type="button" :disabled="busy" @click="closeCreate">取消</button><button type="button" class="btn" :disabled="writeLocked||formPreviewLoading||!!formPreviewError||!formPreview?.ok||!version.trim()||!title.trim()" @click="save(false)">仅保存候选</button><button class="btn btn-primary" :disabled="writeLocked||formPreviewLoading||!!formPreviewError||!formPreview?.ok||!version.trim()||!title.trim()"><LoaderCircle v-if="busy" class="spin" :size="15"/><Save v-else :size="15"/>{{busy?savingStage==='save'?'正在保存候选…':'正在开始校验…':'保存并校验'}}</button></footer></form></section></div>

<div v-if="snapshotOpen" class="modal-backdrop release-dialog-backdrop" @click.self="!busy&&(snapshotOpen=false)"><form ref="snapshotDialog" class="release-snapshot-dialog" role="dialog" aria-modal="true" aria-labelledby="snapshot-title" @keydown="releaseDialogKey" @keydown.esc.stop.prevent="!busy&&(snapshotOpen=false)" @submit.prevent="newSnapshot"><header><h2 id="snapshot-title">导出完整工作快照</h2><button type="button" class="icon-button" :disabled="busy" aria-label="关闭快照表单" @click="snapshotOpen=false"><X :size="18"/></button></header><p>固定 <code>{{branch}}</code> 已提交内容，按字段导出配置打包；仅用于内部核对。</p><label class="release-snapshot-check"><input v-model="snapshotAcknowledged" type="checkbox"/>我已核对整份数据集的内容、导出字段与接收对象。</label><p v-if="snapshotError" class="error-state" role="alert">{{snapshotError}}</p><p v-if="unknownWrite" class="notice" role="alert">操作结果待核对，当前输入保留，未重复生成快照。<button type="button" class="btn" :disabled="loading" @click="recheckUnknown">只读核对状态</button><a v-if="unknownWrite.operationId" :href="'/operations?operation='+encodeURIComponent(unknownWrite.operationId)" target="_blank" rel="noopener" class="btn">打开操作核对（新窗口）</a></p><footer><button type="button" class="btn" :disabled="busy" @click="snapshotOpen=false">取消</button><button class="btn btn-primary" :disabled="writeLocked||!snapshotAcknowledged"><Download :size="14"/>生成工作快照</button></footer></form></div>
</section>
</template>
<style src="./releases.css"></style>
